CREATE OR REPLACE FUNCTION "purchaseOrder_revision_fence"() RETURNS trigger AS $$
BEGIN
  -- The @fenced counter Order.revision (D118):
  -- an update that changes a column it covers sets it to the stored value
  -- plus one, and any other keeps it or adds one.
  IF ROW(NEW.note, NEW.customer_id) IS DISTINCT FROM ROW(OLD.note, OLD.customer_id) THEN
    IF NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
      RAISE EXCEPTION 'purchaseOrder.revision must advance from % to %, not to %', OLD.revision, OLD.revision + 1, NEW.revision
        USING ERRCODE = 'check_violation', CONSTRAINT = 'purchaseOrder_revision_fence';
    END IF;
  ELSIF NEW.revision IS DISTINCT FROM OLD.revision THEN
    IF NEW.revision IS DISTINCT FROM OLD.revision + 1 THEN
      RAISE EXCEPTION 'purchaseOrder.revision must stay at % or advance to %, not move to %', OLD.revision, OLD.revision + 1, NEW.revision
        USING ERRCODE = 'check_violation', CONSTRAINT = 'purchaseOrder_revision_fence';
    END IF;
  END IF;
  RETURN NEW;
END;
$$ LANGUAGE plpgsql
